package br.com.confirmacao.auth.api;import br.com.confirmacao.audit.application.AuditService;import br.com.confirmacao.audit.domain.AuditAction;import br.com.confirmacao.auth.application.*;import br.com.confirmacao.professional.access.ProfessionalAccessService;import br.com.confirmacao.professional.api.CreateProfessionalAccessRequest;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/auth") public class AuthController{private final AuthService auth;private final ProfessionalAccessService registration;private final AuditService audit;private final PasswordResetService resets;public AuthController(AuthService a,ProfessionalAccessService r,AuditService l,PasswordResetService p){auth=a;registration=r;audit=l;resets=p;}@PostMapping("/register")public ResponseEntity<LoginResponse> register(@Valid@RequestBody CreateProfessionalAccessRequest q,HttpServletRequest h){var r=registration.register(q.fullName(),q.email(),q.phone(),q.registrationNumber(),q.password());audit.record(AuditAction.PROFESSIONAL_CREATED,"PROFESSIONAL",r.user().getProfessional().getId(),h);return ResponseEntity.status(HttpStatus.CREATED).body(LoginResponse.from(r));}@PostMapping("/login")public LoginResponse login(@Valid@RequestBody LoginRequest q,HttpServletRequest h){try{var r=auth.authenticate(q.email(),q.password());audit.recordLogin(AuditAction.LOGIN_SUCCESS,r.user(),h);return LoginResponse.from(r);}catch(InvalidCredentialsException e){audit.recordLogin(AuditAction.LOGIN_FAILURE,null,h);throw e;}}@PostMapping("/password-reset/request")public ResponseEntity<ForgotPasswordResponse> request(@Valid@RequestBody ForgotPasswordRequest q,HttpServletRequest h){var r=resets.request(q.email());if(r.user()!=null)audit.recordPasswordReset(AuditAction.PASSWORD_RESET_REQUESTED,r.user(),h);return ResponseEntity.accepted().body(new ForgotPasswordResponse("Se os dados estiverem corretos, você receberá as instruções de recuperação",r.token()));}@PostMapping("/password-reset/confirm")public ResponseEntity<Void> reset(@Valid@RequestBody ResetPasswordRequest q,HttpServletRequest h){var u=resets.reset(q.token(),q.newPassword());audit.recordPasswordReset(AuditAction.PASSWORD_RESET_COMPLETED,u,h);return ResponseEntity.noContent().build();}}
